document.addEventListener('DOMContentLoaded',()=>{const toggleBtn=document.getElementById('togglePassword');const passwordInput=document.getElementById('password');toggleBtn?.addEventListener('click',()=>{const isHidden=passwordInput.type==='password';passwordInput.type=isHidden?'text':'password';toggleBtn.querySelector('i').className=isHidden?'fa-regular fa-eye-slash':'fa-regular fa-eye'})})